const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

/*
<thinking>
1. Search strategy:
   - Use MODIS active fire detections (points): ee.FeatureCollection('MODIS/006/MCD14DL').
   - Date window: 2018-02-03 to 2018-02-04 (exclusive).
   - Regions: Cambodia and Laos from USDOS/LSIB_SIMPLE/2017.
2. Masking strategy:
   - Not applicable for point detections; no cloud masking.
3. Logic to distinguish Valid Zero from Null/Error:
   - Compute global count for the date to validate dataset availability.
   - If global count == 0 -> C1 (Empty Collection for date).
   - If any retrieval throws -> D.
   - Otherwise, compare integer counts; equal/zero are valid and yield B (No) if Cambodia is not greater.
</thinking>
*/

async function runAnalysis() {
  try {
    // 1. Geometry & Time Definitions
    const dateStr = '2018-02-03';
    const start = ee.Date(dateStr);
    const end = start.advance(1, 'day');

    const countries = ee.FeatureCollection('USDOS/LSIB_SIMPLE/2017');

    async function getCountryGeometry(nameOptions) {
      for (const n of nameOptions) {
        const fc = countries.filter(ee.Filter.eq('country_na', n));
        const sz = await fc.size().getInfo();
        if (sz && sz > 0) {
          return fc.geometry();
        }
      }
      return null;
    }

    const cambodiaGeom = await getCountryGeometry(['Cambodia']);
    const laosGeom = await getCountryGeometry(['Laos', 'Lao PDR', "Lao People's Democratic Republic", 'Lao Peoples Democratic Republic']);

    if (!cambodiaGeom || !laosGeom) {
      console.log('Country geometry lookup failed.');
      console.log('D');
      return;
    }

    // 2. Data Acquisition & Check
    const datasetId = 'MODIS/006/MCD14DL';
    const fires = ee.FeatureCollection(datasetId).filterDate(start, end);

    const globalCount = await fires.size().getInfo();
    if (globalCount === null || globalCount === undefined) {
      console.log('Global count is null/undefined.');
      console.log('C3');
      return;
    }
    if (globalCount === 0) {
      console.log(`Dataset: ${datasetId}`);
      console.log(`Date: ${dateStr}`);
      console.log('Global detections: 0');
      console.log('C1');
      return;
    }

    // 3. Processing: regional counts
    const camCount = await fires.filterBounds(cambodiaGeom).size().getInfo();
    const laoCount = await fires.filterBounds(laosGeom).size().getInfo();

    if (
      camCount === null || laoCount === null ||
      camCount === undefined || laoCount === undefined
    ) {
      console.log('Regional count is null/undefined.');
      console.log('C3');
      return;
    }

    // 4. Print concise evidence (<=20 lines)
    console.log(`Dataset: ${datasetId}`);
    console.log(`Date: ${dateStr}`);
    console.log(`Global detections: ${globalCount}`);
    console.log(`Cambodia detections: ${camCount}`);
    console.log(`Laos detections: ${laoCount}`);
    console.log(`Diff (Cambodia - Laos): ${camCount - laoCount}`);

    // 5. Final Answer Tag
    if (camCount > laoCount) {
      console.log('A');
    } else {
      console.log('B');
    }
  } catch (err) {
    // Any exception likely from wrong dataset ID, method error, etc.
    console.log(`Error: ${err && err.message ? err.message : err}`);
    console.log('D');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
